    if (type.indexOf('delete') === 0) return 'delete';
    if (type === 'insertParagraph' || type === 'insertLineBreak') return 'newline';
    if (type.indexOf('insertFrom') === 0) return 'paste';
    if (type.indexOf('format') === 0) return 'format';
