    var multiLine = s && s.end > s.start && flatText(editor.host).slice(s.start, s.end).indexOf('\n') >= 0;
    if (shift || multiLine) run(shift ? 'Decreased indent' : 'Increased indent', function () { indentPlainLines(shift); });
